package io.knowledgebrain.content;
import java.util.*;import java.time.*;import java.util.concurrent.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;
import org.postgresql.ds.PGSimpleDataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.flywaydb.core.Flyway;
import org.springframework.web.server.ResponseStatusException;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_CONTENT_DATABASE_URL",matches=".+")
class DecisionStoreIntegrationTest {
 PGSimpleDataSource ds;JdbcTemplate sql;DecisionStore store;String schema;UuidV7 ids=new UuidV7(Clock.systemUTC());UUID space,actor;String trace="e".repeat(32);
 @BeforeEach void init(){ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_CONTENT_DATABASE_URL"));ds.setUser("brain_content");ds.setPassword(System.getenv("BRAIN_TEST_CONTENT_DATABASE_PASSWORD"));schema="decision_test_"+UUID.randomUUID().toString().replace("-","");new JdbcTemplate(ds).execute("CREATE SCHEMA "+schema);ds.setCurrentSchema(schema);Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();sql=new JdbcTemplate(ds);store=new DecisionStore(ds,Clock.systemUTC());space=ids.next();actor=ids.next();}
 @AfterEach void clean(){sql.execute("DROP SCHEMA "+schema+" CASCADE");}
 String key(){return UUID.randomUUID().toString().replace("-","");}
 DecisionStore.Input input(String title){return new DecisionStore.Input(title," \n\tprivate context\r\n ","Draft outcome","Draft reason","Option A / Option B","DRAFT");}
 DecisionStore.Decision create(){return store.create(space,actor,key(),input("Saved title"),trace).decision();}
 int count(String table){return sql.queryForObject("SELECT count(*) FROM "+table,Integer.class);}
 void status(int code,Runnable fn){assertEquals(code,assertThrows(ResponseStatusException.class,fn::run).getStatusCode().value());}
 @Test void createRetriesReplayOriginalSnapshotAfterEditingArchivalAndPrincipalChange(){var key=key();var first=store.create(space,actor,key,input("First"),trace);assertFalse(first.replay());var v=first.decision();store.change(space,v.decisionId(),actor,1,input("Later"),false,trace);store.change(space,v.decisionId(),actor,2,null,true,trace);var replay=store.create(space,ids.next(),key,input("First"),trace);assertTrue(replay.replay());assertEquals(v,replay.decision());status(409,()->store.create(space,actor,key,input("Different"),trace));assertEquals(1,count("decision"));assertEquals(3,count("decision_revision"));assertEquals(3,count("outbox_event"));assertEquals(actor,store.history(space,v.decisionId(),Long.MAX_VALUE,10).getLast().actorId());}
 @Test void independentStrongVersionsNoopAndRetiredHistorySurviveNewStore(){var v=create();for(int n=1;n<=6;n++)v=store.change(space,v.decisionId(),actor,n,input("Update "+n),false,trace);var id=v.decisionId();assertEquals(v,store.change(space,id,actor,7,input("Update 6"),false,trace));status(412,()->store.change(space,id,actor,1,input("Update 6"),false,trace));assertEquals(List.of(7L,6L,5L,4L,3L),store.history(space,id,Long.MAX_VALUE,5).stream().map(DecisionStore.Revision::version).toList());assertEquals(List.of(2L,1L),store.history(space,id,3,5).stream().map(DecisionStore.Revision::version).toList());var retired=store.change(space,id,actor,7,null,true,trace);assertEquals(retired,new DecisionStore(ds,Clock.systemUTC()).get(space,id));assertEquals(retired,store.change(space,id,actor,8,null,true,trace));status(404,()->store.change(space,id,actor,8,input("Blocked"),false,trace));assertEquals(8,count("decision_revision"));}
 @Test void controlledOutboxFailureRollsBackCreationAndMutationIncludingKeys(){sql.execute("CREATE FUNCTION fail_decision() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'controlled decision failure'; END $$");sql.execute("CREATE TRIGGER fail_decision BEFORE INSERT ON outbox_event FOR EACH ROW EXECUTE FUNCTION fail_decision()");var key=key();assertThrows(RuntimeException.class,()->store.create(space,actor,key,input("Rollback"),trace));assertEquals(0,count("decision"));assertEquals(0,count("decision_revision"));sql.execute("ALTER TABLE outbox_event DISABLE TRIGGER fail_decision");var v=store.create(space,actor,key,input("Rollback"),trace).decision();sql.execute("ALTER TABLE outbox_event ENABLE TRIGGER fail_decision");assertThrows(RuntimeException.class,()->store.change(space,v.decisionId(),actor,1,input("Lost"),false,trace));assertEquals(v,store.get(space,v.decisionId()));assertEquals(1,count("decision_revision"));}
 @Test void concurrentCreateAndEditsHaveOneCanonicalOutcome()throws Exception{var key=key();try(var pool=Executors.newFixedThreadPool(2)){var gate=new CyclicBarrier(2);Callable<DecisionStore.Created> task=()->{gate.await();return store.create(space,actor,key,input("Concurrent"),trace);};var a=pool.submit(task);var b=pool.submit(task);var x=a.get();var y=b.get();assertEquals(x.decision(),y.decision());assertNotEquals(x.replay(),y.replay());var id=x.decision().decisionId();var gate2=new CyclicBarrier(2);Callable<Integer> write=()->{gate2.await();try{store.change(space,id,actor,1,input("Winner"),false,trace);return 200;}catch(ResponseStatusException e){return e.getStatusCode().value();}};var c=pool.submit(write);var e=pool.submit(write);assertEquals(Set.of(200,412),Set.of(c.get(),e.get()));}assertEquals(1,count("decision"));assertEquals(2,count("outbox_event"));}
 @Test void duplicateDecisionsKeepDistinctIdsAndCursorPagesCannotCrossSpaceOrLifecycle(){for(int n=0;n<23;n++)create();var a=store.list(space,"ACTIVE","ALL",null,20);var b=store.list(space,"ACTIVE","ALL",a.nextAfter(),20);assertEquals(20,a.items().size());assertEquals(3,b.items().size());assertNull(b.nextAfter());assertEquals(23,a.items().stream().map(DecisionStore.Summary::decisionId).distinct().count()+b.items().stream().map(DecisionStore.Summary::decisionId).distinct().count());status(400,()->store.list(actor,"ACTIVE","ALL",a.nextAfter(),20));status(400,()->store.list(space,"RETIRED","ALL",a.nextAfter(),20));status(404,()->store.get(actor,a.items().getFirst().decisionId()));assertTrue(store.list(actor,"ACTIVE","ALL",null,20).items().isEmpty());}
 @Test void decisionWritesKeepExistingNoteContentAndEventsIndependent(){var notes=new NoteStore(ds,Clock.systemUTC());var note=notes.create(space,actor,"Own note","Unchanged markdown",trace);var v=create();store.change(space,v.decisionId(),actor,1,input("Edit only decision"),false,trace);assertEquals(note,notes.get(space,note.noteId()));assertEquals(1,notes.history(space,note.noteId(),Long.MAX_VALUE,10).size());assertEquals(2,sql.queryForObject("SELECT count(*) FROM outbox_event WHERE aggregatetype='decision'",Integer.class));}
 @Test void outcomeRequiredForResolutionReopeningRetainsOutcomeAndFilteredCursorsAreBound(){
  var v=create();var invalid=new DecisionStore.Input(v.title(),v.context()," \n\t","Reason","Option B","DECIDED");status(400,()->store.change(space,v.decisionId(),actor,1,invalid,false,trace));assertEquals(1,count("decision_revision"));
  status(400,()->store.change(space,v.decisionId(),actor,1,new DecisionStore.Input(v.title(),v.context(),"Choice"," \n\t","Other","DECIDED"),false,trace));assertEquals(1,count("decision_revision"));
  var completed=store.change(space,v.decisionId(),actor,1,new DecisionStore.Input(v.title(),v.context(),"My explicit outcome","My explicit reason","Option A / Option B","DECIDED"),false,trace);assertEquals("DECIDED",completed.status());assertEquals(1,store.list(space,"ACTIVE","DECIDED",null,20).items().size());assertTrue(store.list(space,"ACTIVE","DRAFT",null,20).items().isEmpty());
  var reopened=store.change(space,v.decisionId(),actor,2,new DecisionStore.Input(v.title(),v.context(),completed.outcome(),completed.rationale(),completed.alternatives(),"DRAFT"),false,trace);assertEquals(completed.outcome(),reopened.outcome());assertEquals(completed.rationale(),reopened.rationale());assertEquals(completed.alternatives(),reopened.alternatives());assertEquals("DECIDED",store.history(space,v.decisionId(),3,5).getFirst().snapshot().status());
  create();var page=store.list(space,"ACTIVE","DRAFT",null,1);assertNotNull(page.nextAfter());status(400,()->store.list(space,"ACTIVE","DECIDED",page.nextAfter(),1));status(400,()->store.list(space,"ACTIVE","ALL",page.nextAfter(),1));
 }
}
